import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    url = f"{API_URL}{user}/repos"
    params = {'per_page': 100, 'page': 1}
    repos = []

    while True:
        response = requests.get(url, params=params)
        response.raise_for_status()
        data = response.json()
        if not data:
            break
        repos.extend(data)
        if len(data) < 100:
            break
        params['page'] += 1

    repo_list = [
        {'name': repo['name'], 'created_at': repo['created_at']}
        for repo in repos
    ]

    repo_list.sort(key=lambda x: x['created_at'])

    return [repo['name'] for repo in repo_list]

